#include "core/supplier_service.h"
#include "core/database.h"
namespace pos { SupplierService::SupplierService(std::shared_ptr<Database> database):db_(std::move(database)){} QString SupplierService::create(const Supplier& supplier){if(supplier.name.trimmed().isEmpty()||supplier.openingBalance<0)throw DatabaseError("invalid supplier");Transaction tx(db_->handle());const auto id=uuid();auto q=db_->prepare("INSERT INTO suppliers(id,name,contact_person,phone,address,opening_balance_paisa,balance_paisa,created_at) VALUES(?,?,?,?,?,?,?,?)");q.bind(1,id);q.bind(2,supplier.name.trimmed());q.bind(3,supplier.contactPerson);q.bind(4,supplier.phone);q.bind(5,supplier.address);q.bind(6,supplier.openingBalance);q.bind(7,supplier.openingBalance);q.bind(8,utcNow());q.execute();if(supplier.openingBalance>0){auto l=db_->prepare("INSERT INTO supplier_ledger(id,supplier_id,entry_type,debit_paisa,credit_paisa,balance_paisa,created_at) VALUES(?,?,?,?,?,?,?)");l.bind(1,uuid());l.bind(2,id);l.bind(3,"opening_balance");l.bind(4,supplier.openingBalance);l.bind(5,0);l.bind(6,supplier.openingBalance);l.bind(7,utcNow());l.execute();}tx.commit();return id;} void SupplierService::update(const Supplier& s){if(s.id.isEmpty()||s.name.trimmed().isEmpty()||s.openingBalance<0)throw DatabaseError("invalid supplier");Transaction tx(db_->handle());auto q=db_->prepare("UPDATE suppliers SET name=?,contact_person=?,phone=?,address=? WHERE id=? AND is_archived=0");q.bind(1,s.name.trimmed());q.bind(2,s.contactPerson);q.bind(3,s.phone);q.bind(4,s.address);q.bind(5,s.id);q.execute();if(sqlite3_changes(db_->handle())!=1)throw DatabaseError("supplier not found");tx.commit();} void SupplierService::archive(const QString& id){Transaction tx(db_->handle());auto q=db_->prepare("UPDATE suppliers SET is_archived=1 WHERE id=? AND is_archived=0");q.bind(1,id);q.execute();if(sqlite3_changes(db_->handle())!=1)throw DatabaseError("supplier not found");tx.commit();} Supplier SupplierService::find(const QString& id)const{auto q=db_->prepare("SELECT id,name,contact_person,phone,address,opening_balance_paisa,is_archived FROM suppliers WHERE id=?");q.bind(1,id);if(!q.stepRow())throw DatabaseError("supplier not found");return{q.text(0),q.text(1),q.text(2),q.text(3),q.text(4),q.integer(5),q.integer(6)!=0};}}
